// Current Linux user identifier, used to isolate Coucou's local IPC namespace.\n\n/// Returns a stable per-user identifier based on the Linux UID.\n///\n/// The function keeps the original name for compatibility with existing\n/// callers, but Linux has no Windows SID, so the UID is used instead.\npub fn current_user_sid() -> Option<String> {\n    let uid = std::process::Command::new("id")\n        .arg("-u")\n        .output()\n        .ok()?;\n\n    if !uid.status.success() {\n        return None;\n    }\n\n    let uid = String::from_utf8(uid.stdout).ok()?;\n    let uid = uid.trim();\n\n    if uid.is_empty() {\n        None\n    } else {\n        Some(format!("uid-{uid}"))\n    }\n}\n